float drawLine(vec2 uv) {
    float value = sin(uv.x * 10.0) / 3.14;
    return smoothstep(0.99, 1.0, 1.0 - abs(value + uv.y - 0.5) * 2.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord/iResolution.xy;
    vec3 backgroundColor = vec3(0, 0, 0);
    vec3 lineColor = vec3(1, 0, 1);
    vec3 line = drawLine(uv) * lineColor;
    fragColor = vec4(backgroundColor + line, 1.0);
}
